plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.spotless)
}

// The complete Material Symbols Rounded set as vector drawables (sym_*), generated by tools/gen_icons.py. The app
// refers to an icon only as a static dev.doona.android.icons.R.drawable.sym_* field, so the release build's resource
// shrinker keeps the ones it names (tools/check-layers.sh bans getIdentifier).
android {
    namespace = "dev.doona.android.icons"
    compileSdk {
        version = release(37) {
            minorApiLevel = 1
        }
    }

    defaultConfig {
        minSdk = 31
    }

    resourcePrefix = "sym_"

    // Whether a newer version exists depends on the date, not the change: Dependabot opens those bumps.
    lint {
        informational += setOf("AndroidGradlePluginVersion", "GradleDependency", "NewerVersionAvailable")
    }
}

spotless {
    format("kts") {
        target("*.kts")
        endWithNewline()
    }
}
